<?php use App\Support\Ui; ?>
<div class="page-heading"><div><span class="eyebrow">CAPACITY</span><h1>Resources</h1><p>Manage the computers used for automatic interview assignment.</p></div><span class="badge neutral"><?= count($resources) ?> resources</span></div><?php if(isset($errors['form'])):?><div class="alert danger" role="alert"><?= $e($errors['form']) ?></div><?php endif; ?>
